import {readBillingCheckoutReview} from './billing-checkout-review';
import type {GuestBalanceScope} from './guest-billing-balance';
export type CheckoutRequest=GuestBalanceScope&{version:1;actor:string;request:string;review:unknown;reason:string};
const uuid=(v:unknown)=>typeof v==='string'&&/^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i.test(v);
function object(v:unknown):Record<string,unknown>{if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Checkout request unavailable.');return v as Record<string,unknown>}
function canonical(v:unknown):string{if(Array.isArray(v))return '['+v.map(canonical).join(',')+']';if(v&&typeof v==='object')return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canonical((v as Record<string,unknown>)[k])).join(',')+'}';return JSON.stringify(v)}
export function validateCheckoutRequest(value:unknown,scope:GuestBalanceScope,actor:string):asserts value is CheckoutRequest{
 const v=object(value);if(Object.keys(v).sort().join(',')!=='actor,property,reason,request,reservation,review,tenant,version'||v.version!==1||v.actor!==actor||v.tenant!==scope.tenant||v.property!==scope.property||v.reservation!==scope.reservation||!uuid(v.request)||typeof v.reason!=='string'||v.reason!==v.reason.trim()||v.reason.length<4||v.reason.length>500)throw Error('Saved checkout request does not match.');
 const r=readBillingCheckoutReview(v.review,scope);if(!r.eligible||!r.balance.available)throw Error('This review cannot be used for checkout.');
}
export function checkoutArgs(p:CheckoutRequest){validateCheckoutRequest(p,p,p.actor);return {p_tenant:p.tenant,p_property:p.property,p_reservation:p.reservation,p_request:p.request,p_review:p.review,p_reason:p.reason,p_confirmed:true}}
export function validateCheckoutReceipt(value:unknown,p:CheckoutRequest){const v=object(value);if(Object.keys(v).sort().join(',')!=='checked_out_at,money_moved,property_id,request_id,reservation_id,status,tenant_id'||v.tenant_id!==p.tenant||v.property_id!==p.property||v.reservation_id!==p.reservation||v.request_id!==p.request||v.status!=='Checked out'||v.money_moved!==false||typeof v.checked_out_at!=='string'||!Number.isFinite(Date.parse(v.checked_out_at)))throw Error('Checkout receipt does not match.');return v}
export function readCheckoutStatus(value:unknown,p:CheckoutRequest){const v=object(value);if(Object.keys(v).sort().join(',')!=='found,property_id,reason,request_id,result,review,tenant_id'||v.tenant_id!==p.tenant||v.property_id!==p.property||v.request_id!==p.request||typeof v.found!=='boolean')throw Error('Checkout status does not match.');if(!v.found){if(v.review!==null||v.reason!==null||v.result!==null)throw Error('Missing checkout has unexpected details.');return null}if(v.reason!==p.reason||canonical(v.review)!==canonical(p.review))throw Error('Recovered checkout details differ.');return validateCheckoutReceipt(v.result,p)}

export function checkoutRetirementArgs(p:CheckoutRequest,reason:string){validateCheckoutRequest(p,p,p.actor);if(typeof reason!=='string'||reason!==reason.trim()||reason.length<4||reason.length>500)throw Error('Enter a cancellation reason.');return {p_tenant:p.tenant,p_property:p.property,p_request:p.request,p_reason:reason,p_confirmed:true}}
export function validateCheckoutRetirement(value:unknown,p:CheckoutRequest,reason:string){checkoutRetirementArgs(p,reason);const v=object(value);if(Object.keys(v).sort().join(',')!=='actor_id,money_moved,property_id,reason,request_id,retired,tenant_id'||v.actor_id!==p.actor||v.tenant_id!==p.tenant||v.property_id!==p.property||v.request_id!==p.request||v.reason!==reason||v.retired!==true||v.money_moved!==false)throw Error('Checkout cancellation receipt does not match.');return v}
